/**
 * Local exam sounds (original, generated by tools/gen-sounds.mjs).
 * Audio is embedded in the bundle as base64 data-URIs — no network needed.
 * A WebAudio fallback is included in case HTMLAudio cannot decode the WAV.
 */
import { START_SOUND_DATA_URI, SUBMIT_SOUND_DATA_URI } from "../audio/soundData";

let muted = false;
export function setSoundMuted(m: boolean) {
  muted = m;
}

function playDataUri(uri: string) {
  if (muted) return;
  try {
    const audio = new Audio(uri);
    audio.volume = 0.7;
    const p = audio.play();
    if (p && typeof p.catch === "function") {
      p.catch(() => fallbackBeep(uri === START_SOUND_DATA_URI));
    }
  } catch {
    fallbackBeep(uri === START_SOUND_DATA_URI);
  }
}

/** WebAudio fallback chimes if the <audio> element path fails. */
function fallbackBeep(isStart: boolean) {
  if (muted) return;
  try {
    const Ctx =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext?: typeof AudioContext })
        .webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    const seq: Array<[number, number, number]> = isStart
      ? [
          [659.25, 0, 0.22],
          [880, 0.13, 0.34],
        ]
      : [
          [523.25, 0, 0.18],
          [659.25, 0.1, 0.18],
          [783.99, 0.2, 0.2],
          [1046.5, 0.32, 0.45],
        ];
    for (const [freq, at, dur] of seq) {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.value = freq;
      gain.gain.setValueAtTime(0.0001, ctx.currentTime + at);
      gain.gain.exponentialRampToValueAtTime(0.22, ctx.currentTime + at + 0.02);
      gain.gain.exponentialRampToValueAtTime(
        0.0001,
        ctx.currentTime + at + dur,
      );
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(ctx.currentTime + at);
      osc.stop(ctx.currentTime + at + dur + 0.05);
    }
    window.setTimeout(() => void ctx.close(), 1600);
  } catch {
    /* no audio hardware — stay silent */
  }
}

export function playStartSound() {
  playDataUri(START_SOUND_DATA_URI);
}

export function playSubmitSound() {
  playDataUri(SUBMIT_SOUND_DATA_URI);
}
